const COLS = 200, ROWS = 63;
const dec = s => {
  const r = atob(s), a = new Uint8Array(r.length);
  for (let i = 0; i < r.length; i++) a[i] = r.charCodeAt(i);
  return a;
};
const LUM = dec("");
const MASK = dec("");
const RIM = dec("");
const RAMP = " .:-=+*#%@";
const FA = ["\\o/", "-o-", "/o\\", "-o-"], FB = ["\\^o^/", "_^o^_", "/vov\\", "_vov_"];
const FONT = '"Space Mono","IBM Plex Mono","Courier New",monospace';
const rnd = (a, b) => a + Math.random() * (b - a);
const sm = (a, b, x) => { x = Math.max(0, Math.min(1, (x - a) / (b - a))); return x * x * (3 - 2 * x); };
const ease = x => x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
const grey = (v, a) => { const g = Math.round(Math.max(0, Math.min(255, v))); return `rgba(${g},${g},${g},${a})`; };
const hash = (c, r) => { const h = Math.sin(c * 127.1 + r * 311.7) * 43758.5453; return h - Math.floor(h); };
function glyph(L, c, r) {
  let i = Math.floor(L / 118 * RAMP.length + (hash(c, r) - .5) * 1.6);
  return RAMP[Math.max(0, Math.min(RAMP.length - 1, i))];
}
const colr = L => L * 1.6 + 10;

// particles = silhouette cells (they become bats)
const P = [];
let mx = 0, my = 0;
for (let r = 0; r < ROWS; r++) {
  for (let c = 0; c < COLS; c++) {
    if (!MASK[r * COLS + c]) continue;
    mx += c;
    my += r;
    P.push({ c, r, L: LUM[r * COLS + c] });
  }
}
mx /= P.length;
my /= P.length;
for (const p of P) {
  const dist = Math.hypot((p.c - mx) / COLS * 1.6, (p.r - my) / ROWS * 1.3);
  p.rim = RIM[p.r * COLS + p.c] === 1;
  p.seed = Math.random();
  p.big = Math.random() < .22;
  p.sp = rnd(.6, 1.4);
  p.sw = rnd(1.2, 3.4) * (Math.random() < .5 ? -1 : 1);
  p.rd = rnd(.35, 1.1);
  p.ph = Math.random() * 6.28;
  p.ra = Math.random() * 6.2832;
  p.rj = Math.random();
  p.dOut = Math.min(.55, dist * .9 + Math.random() * .3);
}

let W, H, dpr, cw, ch, ox, oy, fs;
let cv, ctx, bgc, bx;
let container = null;
let animId = null;
let running = false;
let currentResolve = null;

const T_REVEAL = 2.6, T_HOLD = 2.4, T_OUT = 4.8;
const t2 = T_REVEAL + T_HOLD, t3 = t2 + T_OUT, END = t3 + 2.2;
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
let t0 = 0;

function resizeBatman() {
  if (!container || !cv || !bgc) return;
  dpr = Math.min(2.5, (window.devicePixelRatio || 1) * Math.max(1, window.stageScale || 1));
  W = container.clientWidth || 992;
  H = container.clientHeight || 565;
  cv.width = W * dpr;
  cv.height = H * dpr;
  bgc.width = W * dpr;
  bgc.height = H * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  bx.setTransform(dpr, 0, 0, dpr, 0, 0);
  cw = Math.min(W * .99 / COLS, H * .99 * .55 / ROWS);
  ch = cw / .55;
  fs = ch * 1.0;
  ox = (W - COLS * cw) / 2;
  oy = (H - ROWS * ch) / 2;

  // static textured backdrop (ambient halo of light blooming around bat)
  bx.clearRect(0, 0, W, H);
  bx.font = `${fs}px ${FONT}`;
  bx.textAlign = 'center';
  bx.textBaseline = 'middle';
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (MASK[r * COLS + c]) continue;
      const L = LUM[r * COLS + c], g = glyph(L, c, r);
      if (g === ' ') continue;
      bx.fillStyle = grey(colr(L), .9);
      bx.fillText(g, ox + (c + .5) * cw, oy + (r + .5) * ch);
    }
  }
}

function frame(now) {
  if (!running) return;
  const t = (now - t0) / 1000, time = now / 1000;
  const reveal = Math.min(1, t / T_REVEAL);
  const out = t < t2 ? 0 : Math.min(1, (t - t2) / T_OUT);
  const endF = t > END ? Math.min(1, (t - END) / 1.0) : 0;
  if (bgc) bgc.style.opacity = (sm(0, 1, reveal) * (1 - sm(.02, .55, out))) * (1 - endF);
  if (cv) cv.style.opacity = 1 - endF;

  if (out > 0) {
    ctx.globalCompositeOperation = 'destination-out';
    ctx.fillStyle = 'rgba(0,0,0,.28)';
    ctx.fillRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'source-over';
  } else {
    ctx.clearRect(0, 0, W, H);
  }

  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';
  ctx.font = `${fs}px ${FONT}`;
  const cx0 = ox + (mx + .5) * cw, cy0 = oy + (my + .5) * ch, R = Math.max(W, H) * .6;

  for (const p of P) {
    let s = 0;
    if (out > 0 && !reduce) s = ease(Math.max(0, Math.min(1, (out - p.dOut) / .45)));
    const hx = ox + (p.c + .5) * cw, hy = oy + (p.r + .5) * ch;
    let vis = 1;
    if (reveal < 1) vis = sm(0, 1, reveal * 1.35 - (1 - p.r / ROWS) * .35 - p.seed * .25);

    if (s <= .001) {
      if (vis <= .01) continue;
      // Glowing pure white backlit halo rim
      if (p.rim) {
        ctx.save();
        ctx.shadowColor = '#ffffff';
        ctx.shadowBlur = fs * 2.8;
        ctx.fillStyle = `rgba(255, 255, 255, ${vis})`;
        ctx.fillText('@', hx, hy);
        ctx.restore();
        continue;
      }
      const g = glyph(p.L, p.c, p.r);
      if (g === ' ') continue;
      ctx.fillStyle = grey(colr(p.L) * (1 + Math.sin(time * 3 + p.ph) * .04), .9 * vis);
      ctx.fillText(g, hx, hy);
      continue;
    }

    // storm spiral around the bat logo
    const dx = hx - cx0, dy = hy - cy0, r0 = Math.hypot(dx, dy), a0 = Math.atan2(dy, dx);
    const rad = r0 + R * p.rd * .9 * s;
    const ang = a0 + p.sw * s * 1.5 + Math.sin(time * p.sp + p.ph) * .12 * s;
    let x = cx0 + Math.cos(ang) * rad * (1 + .15 * Math.sin(p.ph));
    let y = cy0 + Math.sin(ang) * rad * .62 - s * H * .1 * p.rd + Math.sin(time * 3 * p.sp + p.ph) * 8 * s;
    const mv = sm(0, .2, s);
    x = hx + (x - hx) * mv;
    y = hy + (y - hy) * mv;

    // loading circle: bats gather into a rotating ring with a fading tail
    const g = (out >= 1 ? 1 : sm(.5, 1, out)) * sm(.3, .8, s);
    const th = p.ra + time * 2.4, rr = Math.min(W, H) * .16 + (p.rj - .5) * fs * 2.6;
    x += (W / 2 + Math.cos(th) * rr - x) * g;
    y += (H / 2 + Math.sin(th) * rr - y) * g;
    const am = 1 - g * (1 - (.08 + .92 * Math.pow(1 - p.ra / 6.2832, 2.2)));
    const bat = sm(.04, .22, s);
    if (bat < .5) {
      ctx.fillStyle = grey(120, (1 - bat * 2) * .6 + .1);
      ctx.fillText(p.L > 30 ? glyph(p.L, p.c, p.r) : '.', x, y);
    } else {
      const depth = .45 + .55 * p.rd / 1.1, flap = Math.floor(time * (7 + p.sp * 4) + p.ph * 2) & 3;
      const lum = 95 + depth * 130 * (.8 + .2 * Math.sin(time * 5 + p.ph)) + g * 60;
      ctx.fillStyle = grey(lum, (bat - .5) * 2 * (.35 + depth * .65) * am);
      ctx.fillText(p.big ? FB[flap] : FA[flap], x, y);
    }
  }

  if (endF >= 1) {
    stopBatman();
    return;
  }
  animId = requestAnimationFrame(frame);
}

function stopBatman() {
  if (!running) return;
  running = false;
  if (animId) {
    cancelAnimationFrame(animId);
    animId = null;
  }
  if (ctx) ctx.clearRect(0, 0, W, H);
  if (bx) bx.clearRect(0, 0, W, H);
  if (container) {
    container.classList.remove('active');
    container.removeEventListener('click', onSkip);
  }
  document.removeEventListener('keydown', onKey);
  window.removeEventListener('resize', resizeBatman);

  if (currentResolve) {
    const res = currentResolve;
    currentResolve = null;
    res();
  }
}

function onSkip() {
  stopBatman();
}

function onKey(e) {
  if (['Escape', ' ', 'Enter'].includes(e.key)) {
    stopBatman();
  }
}

window.stopBatman = stopBatman;
window.runBatmanAnimation = function() {
  return new Promise(resolve => {
    container = document.getElementById('batman-container');
    cv = document.getElementById('batman-c');
    bgc = document.getElementById('batman-bg');
    if (!container || !cv || !bgc) {
      resolve();
      return;
    }

    currentResolve = resolve;
    ctx = cv.getContext('2d');
    bx = bgc.getContext('2d');
    container.classList.add('active');
    resizeBatman();

    window.addEventListener('resize', resizeBatman);
    container.addEventListener('click', onSkip);
    document.addEventListener('keydown', onKey);

    t0 = performance.now();
    running = true;
    animId = requestAnimationFrame(frame);
  });
};
